#!/usr/bin/env python3

import rclpy
from rclpy.node import Node
from std_msgs.msg import Bool
from sensor_msgs.msg import CompressedImage, JointState
from geometry_msgs.msg import Twist
import cv2
import numpy as np

class PressButton(Node):
    def __init__(self):
        super().__init__('press_button')

        self.auto_mode = False
        self.button_pressed = False
        self.state = "IDLE"
        self.press_start_time = None

        # Publicadores
        self.joint_pub = self.create_publisher(JointState, '/joint_states', 10)
        self.cmd_pub = self.create_publisher(Twist, '/cmd_vel', 10)
        self.tool_joint_name = '2J1'

        # Suscripciones
        self.create_subscription(Bool, '/button_detector', self.button_callback, 10)
        self.create_subscription(CompressedImage, '/image_raw/compressed', self.image_callback, 10)

        # Timer no bloqueante
        self.create_timer(0.05, self.control_loop)

        self.get_logger().info("Nodo PressButton iniciado")

    def button_callback(self, msg: Bool):
        if msg.data and not self.auto_mode:
            self.auto_mode = True
            self.state = "SEARCHING"
            self.get_logger().info("Modo automático activado")

    def image_callback(self, msg: CompressedImage):
        if not self.auto_mode or self.button_pressed or self.state != "SEARCHING":
            return

        # Decodificar imagen
        np_arr = np.frombuffer(msg.data, np.uint8)
        cv_image = cv2.imdecode(np_arr, cv2.IMREAD_COLOR)
        if cv_image is None:
            self.get_logger().warn("No se pudo decodificar la imagen")
            return

        # Mostrar imagen
        cv2.imshow("Camera View", cv_image)
        cv2.waitKey(1)

        # Convertir a HSV para detectar rojo
        hsv = cv2.cvtColor(cv_image, cv2.COLOR_BGR2HSV)

        # Máscara rojo (umbral más bajo)
        lower_red1 = np.array([0, 50, 50])
        upper_red1 = np.array([10, 255, 255])
        lower_red2 = np.array([170, 50, 50])
        upper_red2 = np.array([180, 255, 255])
        mask1 = cv2.inRange(hsv, lower_red1, upper_red1)
        mask2 = cv2.inRange(hsv, lower_red2, upper_red2)
        mask = mask1 | mask2

        contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        if len(contours) == 0:
            self.get_logger().info("No se detecta botón rojo. Nodo terminado.")
            rclpy.shutdown()
            return

        largest_contour = max(contours, key=cv2.contourArea)
        area = cv2.contourArea(largest_contour)
        if area < 50:  # umbral más bajo para contornos pequeños
            self.get_logger().info("Contorno muy pequeño. Continuando búsqueda.")
            return

        # Dibujar contorno detectado
        cv2.drawContours(cv_image, [largest_contour], -1, (0, 255, 0), 2)
        cv2.imshow("Camera View", cv_image)
        cv2.waitKey(1)

        self.get_logger().info("Botón rojo detectado")
        self.state = "LOWERING_TOOL"

    def control_loop(self):
        if self.state == "LOWERING_TOOL":
            # Bajar herramienta
            msg = JointState()
            msg.name = [self.tool_joint_name]
            msg.position = [220_000.0]
            self.joint_pub.publish(msg)
            self.get_logger().info(f"Herramienta bajada a {msg.position[0]}")
            self.state = "PRESSING"
            self.press_start_time = self.get_clock().now()

        elif self.state == "PRESSING":
            # Publicar cmd_vel mientras avanza 3 segundos
            elapsed = (self.get_clock().now() - self.press_start_time).nanoseconds * 0.5e-9
            twist = Twist()
            if elapsed < 6.0:
                twist.linear.x = 0.2  # velocidad lenta
                self.cmd_pub.publish(twist)
            else:
                twist.linear.x = 0.0  # parar robot
                self.cmd_pub.publish(twist)
                self.get_logger().info("Acción completada")
                self.button_pressed = True
                rclpy.shutdown()

def main(args=None):
    rclpy.init(args=args)
    node = PressButton()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        cv2.destroyAllWindows()
        rclpy.shutdown()

if __name__ == "__main__":
    main()
